(585387, 61062, 12108, '<td valign="top">Nice colors as well as many interesting textures. (6)</td>', 'Nice colors as well as many interesting textures. (6)', '2004-02-18 11:08:33.000000', NULL, 1),
(585388, 59833, 14986, '<td valign="top">I like this one.   Good angle, different texture presented and very nice lighting.</td>', 'I like this one.   Good angle, different texture presented and very nice lighting.', '2004-02-18 11:08:42.000000', NULL, 1),
(585389, 60108, 14986, '<td valign="top">Very nice.  I like the lighting.   Very nice composition and I like the sugar sides and plain sides being varied.  Very good texture.</td>', 'Very nice.  I like the lighting.   Very nice composition and I like the sugar sides and plain sides being varied.  Very good texture.', '2004-02-18 11:09:38.000000', NULL, 1),
