(585417, 60037, 327, '<td valign="top">Unusual piece. Too bad the street light is popping out of the top.</td>', 'Unusual piece. Too bad the street light is popping out of the top.', '2004-02-18 11:19:04.000000', NULL, 1),
(585418, 60963, 11467, '<td valign="top">Nice. Maybe a little too bright on the right</td>', 'Nice. Maybe a little too bright on the right', '2004-02-18 11:19:17.000000', NULL, 1),
(585419, 60875, 327, '<td valign="top">I think this needed a bit more to make this interesting.</td>', 'I think this needed a bit more to make this interesting.', '2004-02-18 11:19:44.000000', NULL, 1),
