(585641, 60883, 14603, '<td valign="top">Nice sharp image...well composed. (it`s making me hungry..so it must be good)<br/>8</td>', 'Nice sharp image...well composed. (it`s making me hungry..so it must be good)8', '2004-02-18 12:56:50.000000', NULL, 1),
(585642, 61113, 13897, '<td valign="top">Very nice. One of the best of the bunch. I like the angle and the lighting. 8</td>', 'Very nice. One of the best of the bunch. I like the angle and the lighting. 8', '2004-02-18 12:56:54.000000', NULL, 1),
(585645, 60762, 10887, '<td valign="top">Great idea and well done!</td>', 'Great idea and well done!', '2004-02-18 12:57:51.000000', NULL, 1),
(585646, 61057, 13897, '<td valign="top">Nice job. It''s one of the few "soft" textures that I liked. Good lighting and focus. 8</td>', 'Nice job. It''s one of the few "soft" textures that I liked. Good lighting and focus. 8', '2004-02-18 12:57:55.000000', NULL, 1),
(585648, 60315, 13897, '<td valign="top">One of the best of the bunch. Good lighting and focus. 8</td>', 'One of the best of the bunch. Good lighting and focus. 8', '2004-02-18 12:58:52.000000', NULL, 1),
