(589357, 60404, 17203, '<td valign="top">Very interesting texture, and nice that you didn''t just center it in the frame. Good job! 8</td>', 'Very interesting texture, and nice that you didn''t just center it in the frame. Good job! 8', '2004-02-19 21:50:51.000000', NULL, 1),
(589362, 59935, 12674, '<td valign="top">Very creative and excellent color.</td>', 'Very creative and excellent color.', '2004-02-19 21:52:26.000000', NULL, 1),
