INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(589404, 61103, 17081, '<td valign="top">The thumbnail of this was more effective than the fullsize shot.</td>', 'The thumbnail of this was more effective than the fullsize shot.', '2004-02-19 22:11:24.000000', NULL, 1),
(589406, 59916, 15242, '<td valign="top">It''s not really saying texture to me.  It is quite interesting, but maybe too busy.</td>', 'It''s not really saying texture to me.  It is quite interesting, but maybe too busy.', '2004-02-19 22:12:16.000000', NULL, 1),
(589407, 61076, 15242, '<td valign="top">Deepen the DOF.  Take it so there is no back ground and I might like it better.</td>', 'Deepen the DOF.  Take it so there is no back ground and I might like it better.', '2004-02-19 22:13:44.000000', NULL, 1),
(589408, 60185, 10818, '<td valign="top">What a great shot.....nice texture.. very orignal.  Good luck !</td>', 'What a great shot.....nice texture.. very orignal.  Good luck !', '2004-02-19 22:14:57.000000', NULL, 1),
(589410, 60011, 15242, '<td valign="top">Nice composition, Great shot</td>', 'Nice composition, Great shot', '2004-02-19 22:17:21.000000', NULL, 1),
(589412, 60742, 17203, '<td valign="top">Too much about color, rather than texture. I think it would have worked better even as B&amp;W.</td>', 'Too much about color, rather than texture. I think it would have worked better even as B&W.', '2004-02-19 22:17:50.000000', NULL, 1),
(589413, 60135, 6600, '<td valign="top">Nice contrast, somewhat abstract, good job.</td>', 'Nice contrast, somewhat abstract, good job.', '2004-02-19 22:19:02.000000', NULL, 1),
(589415, 60887, 15242, '<td valign="top">A very difficult shot to take.  Dead on like this you lose the shadows and depth.  A nice subject to shoot.</td>', 'A very difficult shot to take.  Dead on like this you lose the shadows and depth.  A nice subject to shoot.', '2004-02-19 22:19:38.000000', NULL, 1),
(589416, 61107, 17203, '<td valign="top">Very nice. Just a little more focus and I''d have voted higher. 7</td>', 'Very nice. Just a little more focus and I''d have voted higher. 7', '2004-02-19 22:19:46.000000', NULL, 1),
(589418, 61113, 6600, '<td valign="top">Very detailed with good lighting and exposure. Nice job.</td>', 'Very detailed with good lighting and exposure. Nice job.', '2004-02-19 22:20:16.000000', NULL, 1),
(589421, 60226, 17203, '<td valign="top">Koosh. Sheesh. What a good idea!</td>', 'Koosh. Sheesh. What a good idea!', '2004-02-19 22:21:08.000000', NULL, 1),
(589422, 60037, 15242, '<td valign="top">Lighting is killing you here.  Photos of art never seem to work real well.</td>', 'Lighting is killing you here.  Photos of art never seem to work real well.', '2004-02-19 22:21:37.000000', NULL, 1),
(589423, 60664, 17203, '<td valign="top">Beautiful texture find! Just a bit more focus...</td>', 'Beautiful texture find! Just a bit more focus...', '2004-02-19 22:21:47.000000', NULL, 1),
(589425, 61119, 17203, '<td valign="top">I''m impressed that you were able to capture the tiny white-on-white texture within the texture. Well done!</td>', 'I''m impressed that you were able to capture the tiny white-on-white texture within the texture. Well done!', '2004-02-19 22:22:50.000000', NULL, 1),
