(589427, 60766, 17203, '<td valign="top">Great texture contrast and well executed. Good job! 8</td>', 'Great texture contrast and well executed. Good job! 8', '2004-02-19 22:23:28.000000', NULL, 1),
(589430, 59785, 17203, '<td valign="top">This might have worked, but I don''t see anything in focus, and little variation in value. Perhaps if you stepped back and used a stronger light source?</td>', 'This might have worked, but I don''t see anything in focus, and little variation in value. Perhaps if you stepped back and used a stronger light source?', '2004-02-19 22:24:56.000000', NULL, 1),
