(589455, 60852, 14476, '<td valign="top">This is a lovely textural image of your pet.  I''m sure this beauty held still patiently untill you finished all the photographs your heart desired.  Nice job on the challenge.</td>', 'This is a lovely textural image of your pet.  I''m sure this beauty held still patiently untill you finished all the photographs your heart desired.  Nice job on the challenge.', '2004-02-19 22:34:19.000000', NULL, 1),
(589457, 60069, 17203, '<td valign="top">This might have been great, but the light was way too harsh.</td>', 'This might have been great, but the light was way too harsh.', '2004-02-19 22:35:29.000000', NULL, 1),
(589458, 61053, 15242, '<td valign="top">This was taken through glass, and it really shows.  Photo''s of other people''s art rarely make a good photo.</td>', 'This was taken through glass, and it really shows.  Photo''s of other people''s art rarely make a good photo.', '2004-02-19 22:35:50.000000', NULL, 1),
(589459, 60192, 14476, '<td valign="top">This is a beautifully photographed and nicely lit image that fits the Challenge perfectly.  It might have more impact if you had been able to introduce a different shape or color into your composition to give it that "wow" factor.  Nevertheless, it is a creditable job.</td>', 'This is a beautifully photographed and nicely lit image that fits the Challenge perfectly.  It might have more impact if you had been able to introduce a different shape or color into your composition to give it that "wow" factor.  Nevertheless, it is a creditable job.', '2004-02-19 22:36:18.000000', NULL, 1),
