(591114, 60921, 14837, '<td valign="top">Great contrast and lighting.  I think is great in B&amp;W.</td>', 'Great contrast and lighting.  I think is great in B&W.', '2004-02-20 18:29:25.000000', NULL, 1),
(591116, 59953, 2792, '<td valign="top">Great abstract, love the colors! Maybe just a tad too sof.</td>', 'Great abstract, love the colors! Maybe just a tad too sof.', '2004-02-20 18:29:40.000000', NULL, 1),
(591118, 60088, 14837, '<td valign="top">I have to giggle when I see this.  It looks like bug guts!  :)  Nice shot!</td>', 'I have to giggle when I see this.  It looks like bug guts!  :)  Nice shot!', '2004-02-20 18:31:19.000000', NULL, 1),
(591147, 59817, 3032, '<td valign="top">My only 10 for this challenge.<br/>Excellent spotting.<br/>Love the colors and the choice of dof of the subject vs the relatively uniform colored and balanced background. Great composition.</td>', 'My only 10 for this challenge.Excellent spotting.Love the colors and the choice of dof of the subject vs the relatively uniform colored and balanced background. Great composition.', '2004-02-20 18:49:22.000000', NULL, 1),
(591149, 60315, 3032, '<td valign="top">Busy, but very interesting patterns. Like the toning, keeps me entertained for a while, good job. 9</td>', 'Busy, but very interesting patterns. Like the toning, keeps me entertained for a while, good job. 9', '2004-02-20 18:50:17.000000', NULL, 1),
