INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(592329, 60769, 11769, '<td valign="top">Looks to be Acrylic paint and quite loose. I myself like Oils that are stiffer in consistency. Notwithstanding, I just love to paint and have done so for most of my life. This picture is just wonderful. I can feel the texture of the paint as it is applied to the canvas. Smooth and silky. Also like the composition.</td>', 'Looks to be Acrylic paint and quite loose. I myself like Oils that are stiffer in consistency. Notwithstanding, I just love to paint and have done so for most of my life. This picture is just wonderful. I can feel the texture of the paint as it is applied to the canvas. Smooth and silky. Also like the composition.', '2004-02-21 17:28:02.000000', NULL, 1),
(592332, 61092, 11769, '<td valign="top">You hit it on the nail here. What a feeling of texture.</td>', 'You hit it on the nail here. What a feeling of texture.', '2004-02-21 17:29:34.000000', NULL, 1),
(592341, 61052, 13728, '<td valign="top">Nice texture although a little out of focus..adding a little more contrast would have highlighted the texture a little more also</td>', 'Nice texture although a little out of focus..adding a little more contrast would have highlighted the texture a little more also', '2004-02-21 17:39:09.000000', NULL, 1),
(592343, 60013, 17228, '<td valign="top">Certainly gets your attention. Nice sharp focus. Really like how the eyelid is raised to an unnatural extent. Curious how it would have looked in B&amp;W also. Cool</td>', 'Certainly gets your attention. Nice sharp focus. Really like how the eyelid is raised to an unnatural extent. Curious how it would have looked in B&W also. Cool', '2004-02-21 17:42:27.000000', NULL, 1),
(592344, 60588, 13728, '<td valign="top">Wow, great shot, what an interesting and yet ugly and beautiful at the same time creature.  Great entry for challenge.  nice focus and DOF</td>', 'Wow, great shot, what an interesting and yet ugly and beautiful at the same time creature.  Great entry for challenge.  nice focus and DOF', '2004-02-21 17:42:46.000000', NULL, 1),
(592345, 61031, 13728, '<td valign="top">nice idea, but I think this shot would have been really effective if you had just showed a closeup of grandpas hands.  maybe holding the childs hands to show contrast</td>', 'nice idea, but I think this shot would have been really effective if you had just showed a closeup of grandpas hands.  maybe holding the childs hands to show contrast', '2004-02-21 17:45:25.000000', NULL, 1),
(592346, 61130, 13728, '<td valign="top">I think this needs a better DOF and a little more contrast to be really effective</td>', 'I think this needs a better DOF and a little more contrast to be really effective', '2004-02-21 17:46:57.000000', NULL, 1),
(592347, 60880, 13728, '<td valign="top">Needs to be better focused. but nice texture</td>', 'Needs to be better focused. but nice texture', '2004-02-21 17:47:29.000000', NULL, 1),
