(593135, 60766, 804, '<td valign="top">Good example of how the right lighting can show a very subtle texture.</td>', 'Good example of how the right lighting can show a very subtle texture.', '2004-02-22 10:49:11.000000', NULL, 1),
(593136, 60925, 13591, '<td valign="top">A little tighter crop at the top perhaps, but nice job.</td>', 'A little tighter crop at the top perhaps, but nice job.', '2004-02-22 10:49:31.000000', NULL, 1),
(593137, 60039, 13591, '<td valign="top">This makes me hungry.  mmmmmm</td>', 'This makes me hungry.  mmmmmm', '2004-02-22 10:50:12.000000', NULL, 1),
(593138, 59984, 13591, '<td valign="top">Very nice depth of field.</td>', 'Very nice depth of field.', '2004-02-22 10:51:15.000000', NULL, 1),
