(595542, 60999, 4793, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2004-02-24 01:05:04.000000', NULL, 1),
(595543, 60093, 259, '<td valign="top">nice lighting.  on the downside, i''m not a fan of the fading border look.  i think they attract attention away from the picture.</td>', 'nice lighting.  on the downside, i''m not a fan of the fading border look.  i think they attract attention away from the picture.', '2004-02-24 01:08:29.000000', NULL, 1),
(595544, 60966, 4793, '<td valign="top">A beautiful well done shot.</td>', 'A beautiful well done shot.', '2004-02-24 01:09:45.000000', NULL, 1),
(595546, 60845, 259, '<td valign="top">i like your use of lighting.  however, while there is nothing really wrong with your composition, i feel it could be stronger.  the perspective in your shot is rather normal.  a more abnormal look at a normal object seems to make more interesting pictures.</td>', 'i like your use of lighting.  however, while there is nothing really wrong with your composition, i feel it could be stronger.  the perspective in your shot is rather normal.  a more abnormal look at a normal object seems to make more interesting pictures.', '2004-02-24 01:15:36.000000', NULL, 1),
(595556, 59997, 10268, '<td valign="top">It''s really washed out.  I like it though, but the colors are just so bad.  4.</td>', 'It''s really washed out.  I like it though, but the colors are just so bad.  4.', '2004-02-24 01:43:15.000000', NULL, 1),
