(595981, 60947, 14620, '<td valign="top">very nice details. I like your color choice as well.</td>', 'very nice details. I like your color choice as well.', '2004-02-24 11:38:30.000000', NULL, 1),
(595982, 60572, 16850, '<td valign="top">Whew, that dirt saved the photo!</td>', 'Whew, that dirt saved the photo!', '2004-02-24 11:39:07.000000', NULL, 1),
